class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int ones=0,twos=0;
        for(auto it:nums)
        {
            ones=(ones^it)&(~twos);
            twos=(twos^it)&(~ones);
        }
        return ones;
    }
};
//Approach 2: Using conventional technique.
//Editorial: https://leetcode.com/problems/single-number-ii/solutions/43313/a-general-c-solution-for-these-type-problems/?orderBy=most_votes
class Solution {
public:
    int singleNumber(vector<int>& nums) {
        vector<int> bits(32,0);
        for(auto it:nums)
        {
            int val=it;
            for(int i=0;i<32;i++)
            {
                bits[i]+=(val&1);
                val>>=1;
                if(!val)
                    break;
            }
        }
        int ans=0;
        for(int i=0;i<32;i++)
        {
            int rem=bits[i]%3;
            if(rem)
                ans+=(1<<i);
        }
        return ans;
    }
};

class Solution:
    # @param {integer[]} nums
    # @return {integer}
    def singleNumber(self, nums):
        bins = []
        maxlen = 0
        negatives = 0
        for num in nums:
            if num <0:
                negatives += 1
                num = -num
            bins.append(bin(num)[2:])
            maxlen = max(maxlen, len(bin(num))-2)
        sums = [0 for n in range(maxlen)]
        for i in range(len(bins)):
            bins[i] = '0'*(maxlen-len(bins[i]))+bins[i]
            for j in range(maxlen):
                sums[j] += int(bins[i][j])

        for j in range(maxlen):
            sums[j] = sums[j]%3
        negative = negatives %3
        s = ''.join([str(k) for k in sums])
        val = int(s, base=2)
        return -val if negative else val

